import test from 'node:test';
import assert from 'node:assert/strict';
import { createLiveEditorialCycle } from '../src/editorial/live-cycle.js';
import { publishApprovedLiveUnit } from '../src/production/live-editorial-publish.js';
const unit = (category) => createLiveEditorialCycle().units.find(item => item.category === category);
function adapter(target = unit('AI_INTELLIGENCE'), options = {}) { const calls = { publish: 0 }; let status = 'DRAFT'; let url = null; const post = () => ({ postId: 'draft-1', title: target.title, content: target.render.html.match(/<article\b[^>]*>[\s\S]*<\/article>/i)[0], status, url, labels: [target.render.label] }); return { calls, adapter: { readPost: async () => post(), findMatches: async () => [post(), ...(options.duplicate ? [{ ...post(), postId: 'other' }] : [])], publishDraft: async () => { calls.publish++; status = 'PUBLISHED'; url = 'https://motusnova.blogspot.com/2026/10/live.html'; if (options.failPublishAfterSuccess)
            throw new Error('uncertain response'); return { postId: 'draft-1', publicPostUrl: url, publishedAt: '2026-10-06T20:00:00+09:00' }; }, fetchPublic: async () => ({ status: 200, body: `<html><title>${target.title}</title><body>MOTUS</body></html>` }) } }; }
test('approved live unit publishes exactly once and prepares downstream registrations', async () => { const target = unit('AI_INTELLIGENCE'); const fake = adapter(target); const result = await publishApprovedLiveUnit({ unit: target, draftPostId: 'draft-1', approvedAt: '2026-10-06T19:00:00+09:00', adapter: fake.adapter }); assert.equal(result.state, 'PUBLISHED'); assert.equal(result.publishCallCount, 1); assert.equal(fake.calls.publish, 1); assert.equal(result.searchRegistration?.googleInspectionState, 'QUEUED'); assert.equal(result.searchRegistration?.visibility.google.indexed, null); assert.ok(result.libraryRegistration?.relatedEvents.length); assert.equal(result.weeklyFeed?.state, 'PUBLISHED'); assert.equal(result.pdf.visibility, 'PRIVATE'); });
test('extra remote duplicate blocks publish', async () => { const target = unit('AI_INTELLIGENCE'); const fake = adapter(target, { duplicate: true }); const result = await publishApprovedLiveUnit({ unit: target, draftPostId: 'draft-1', approvedAt: '2026-10-06T19:00:00+09:00', adapter: fake.adapter }); assert.equal(result.state, 'HOLD'); assert.equal(result.remoteDuplicateCount, 1); assert.equal(fake.calls.publish, 0); });
test('uncertain publish response is recovered by readback without retry', async () => { const target = unit('AI_INTELLIGENCE'); const fake = adapter(target, { failPublishAfterSuccess: true }); const result = await publishApprovedLiveUnit({ unit: target, draftPostId: 'draft-1', approvedAt: '2026-10-06T19:00:00+09:00', adapter: fake.adapter }); assert.equal(result.state, 'PUBLISHED'); assert.equal(fake.calls.publish, 1); assert.ok(result.audit.some(item => item.event === 'PUBLISH_RESPONSE_RECOVERED')); });
test('tampered draft fails fingerprint and remains HOLD', async () => { const target = unit('AI_INTELLIGENCE'); const fake = adapter(target); const original = fake.adapter.readPost; fake.adapter.readPost = async (id) => ({ ...await original(id), content: '<article>tampered</article>' }); const result = await publishApprovedLiveUnit({ unit: target, draftPostId: 'draft-1', approvedAt: '2026-10-06T19:00:00+09:00', adapter: fake.adapter }); assert.equal(result.state, 'HOLD'); assert.equal(result.preflight?.fingerprint, false); assert.equal(fake.calls.publish, 0); });
